{
  "name": "agent-teams-controller",
  "version": "1.0.0",
  "private": true,
  "description": "Controller package for Claude agent teams operations",
  "type": "commonjs",
  "main": "src/index.js",
  "files": [
    "src",
    "dist"
  ],
  "scripts": {
    "build": "node ./scripts/build.mjs",
    "test": "vitest run --config vitest.config.js",
    "test:watch": "vitest --config vitest.config.js"
  },
  "devDependencies": {
    "proper-lockfile": "4.1.2"
  },
  "engines": {
    "node": ">=24.15.0 <25 || >=26 <27"
  }
}

import { copyFile, mkdir, readdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.resolve(__dirname, '..');
const srcDir = path.join(packageRoot, 'src');
const distDir = path.join(packageRoot, 'dist');

async function copyRecursive(sourceDir, targetDir) {
  await mkdir(targetDir, { recursive: true });
  const entries = await readdir(sourceDir, { withFileTypes: true });

  for (const entry of entries) {
    const sourcePath = path.join(sourceDir, entry.name);
    const targetPath = path.join(targetDir, entry.name);

    if (entry.isDirectory()) {
      await copyRecursive(sourcePath, targetPath);
      continue;
    }

    if (entry.isFile()) {
      await copyFile(sourcePath, targetPath);
    }
  }
}

await rm(distDir, { recursive: true, force: true });
await mkdir(distDir, { recursive: true });
await copyRecursive(srcDir, distDir);

import { fileViewerRenderers } from '@file-viewer/vite-plugin';
import { defineConfig } from 'electron-vite'
import { sentryVitePlugin } from '@sentry/vite-plugin'
import react from '@vitejs/plugin-react'
import { execSync } from 'child_process'
import { readFileSync } from 'fs'
import { resolve } from 'path'
import { loadEnv, type Plugin } from 'vite'
import {
  isOfficialPostHogReleaseBuild,
  resolvePostHogBuildKey,
} from './src/shared/utils/posthogBuildPolicy'
import { INHERITED_HARNESS_ENV_BANNER } from './src/main/utils/inheritedHarnessEnv'
import { resolveSentryBuildEnvironment } from './src/shared/utils/sentryBuildPolicy'
import { pinDocumentPreviewWorkers, sentryArtifactInventoryPlugin } from './scripts/build/sentryArtifactInventory'
import { resolveSentryBuildIdentity } from './scripts/build/sentryBuildIdentity'

// Read all production dependencies from package.json
// so they get bundled into the main process output.
// This avoids pnpm symlink issues with electron-builder's asar packaging.
const pkg = JSON.parse(readFileSync(resolve(__dirname, 'package.json'), 'utf-8'))
const prodDeps = Object.keys(pkg.dependencies || {})
const terminalPlatformLocalRoot = resolveTerminalPlatformLocalRoot()
const terminalPlatformSdkAliases = createTerminalPlatformSdkAliases()
const rendererDependencyEsbuildTarget = 'esnext'
const localEnv = loadEnv(process.env.NODE_ENV ?? 'development', __dirname, '')
const sentryBuildCovered = Boolean(process.env.SENTRY_AUTH_TOKEN)
const { gitSha: buildGitSha, buildId } = resolveSentryBuildIdentity({
  env: process.env,
  localEnv,
  covered: sentryBuildCovered,
  readGitSha: () => execSync('git rev-parse HEAD', {
    cwd: __dirname,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'ignore'],
  }),
})
const sentryEnvironment = resolveSentryBuildEnvironment(process.env)
const releaseChannel = resolveReleaseChannel()
const officialPostHogBuild = isOfficialPostHogReleaseBuild(process.env)
const posthogKey = resolvePostHogBuildKey(process.env, localEnv)
const posthogHost =
  process.env.POSTHOG_HOST ??
  localEnv.POSTHOG_HOST ??
  process.env.VITE_POSTHOG_HOST ??
  localEnv.VITE_POSTHOG_HOST ??
  'https://eu.i.posthog.com'

// Fastify and its plugins rely on runtime module resolution that breaks when bundled.
const runtimeExternalDeps = new Set([
  'node-pty',
  'better-sqlite3',
  'agent-teams-controller',
  'terminal-platform-node',
  'ws',
  'fastify',
  '@fastify/cors',
  '@fastify/static',
])

// node-pty is a native addon that cannot be bundled by Rollup.
// It must remain external and be loaded at runtime via require().
const bundledDeps = prodDeps.filter(d => !runtimeExternalDeps.has(d))

function firstNonEmptyEnv(...values: Array<string | undefined>): string {
  return values.map(value => value?.trim() ?? '').find(Boolean) ?? ''
}

function resolveReleaseChannel(): string {
  return (
    firstNonEmptyEnv(
      process.env.RELEASE_CHANNEL,
      localEnv.RELEASE_CHANNEL,
      process.env.AGENT_TEAMS_RELEASE_CHANNEL,
      localEnv.AGENT_TEAMS_RELEASE_CHANNEL,
      process.env.VITE_RELEASE_CHANNEL,
      localEnv.VITE_RELEASE_CHANNEL
    ) || sentryEnvironment
  )
}

// Rollup plugin: stub out native .node addon imports with empty modules.
// ssh2 and cpu-features use optional native bindings that can't be bundled,
// but they have pure JS fallbacks when the native module isn't available.
function nativeModuleStub(): Plugin {
  const STUB_ID = '\0native-stub'
  const NODE_MODULE_RE = /\.node(?:\?.*)?$/
  return {
    name: 'native-module-stub',
    enforce: 'pre',
    resolveId(source) {
      if (NODE_MODULE_RE.test(source)) return `${STUB_ID}:${source}`
      return null
    },
    load(id) {
      if (id.startsWith(STUB_ID) || NODE_MODULE_RE.test(id)) return 'export default {}'
      return null
    }
  }
}

const sentrySourceMapTargets = {
  main: {
    assets: ['./dist-electron/main/**/*.{js,cjs,mjs,map}'],
    filesToDeleteAfterUpload: ['./dist-electron/main/**/*.map'],
  },
  renderer: {
    assets: ['./out/renderer/**/*.{js,cjs,mjs,map}'],
    filesToDeleteAfterUpload: ['./out/renderer/**/*.map'],
  },
} as const

const sourceMapSetting = process.env.AGENT_TEAMS_DISABLE_SOURCEMAPS === '1' ? false : 'hidden'

// Sentry source map upload - only active in CI when SENTRY_AUTH_TOKEN is set.
function createSentryPlugins(target: keyof typeof sentrySourceMapTargets): Plugin[] {
  const covered = sentryBuildCovered
  return [
    ...(covered ? [sentryVitePlugin({
      org: process.env.SENTRY_ORG ?? 'quant-jump-pro',
      project: process.env.SENTRY_PROJECT ?? 'electron',
      authToken: process.env.SENTRY_AUTH_TOKEN,
      telemetry: false,
      release: { name: `agent-teams-ai@${pkg.version}` },
      sourcemaps: sentrySourceMapTargets[target],
    }) as Plugin] : []),
    sentryArtifactInventoryPlugin({
      target,
      covered,
      release: `agent-teams-ai@${pkg.version}`,
      buildId,
      gitSha: buildGitSha,
      ...(covered && target === 'renderer'
        ? { documentPreviewWorkers: pinDocumentPreviewWorkers(__dirname) }
        : {}),
      evidenceDirectory: resolve(
        __dirname,
        '.artifacts/sentry',
        buildGitSha || 'unknown',
        buildId || 'unknown'
      ),
    }),
  ]
}

function resolveTerminalPlatformLocalRoot(): string | null {
  const value =
    process.env.CLAUDE_TERMINAL_PLATFORM_ROOT?.trim() || process.env.TERMINAL_PLATFORM_ROOT?.trim()
  return value ? resolve(__dirname, value) : null
}

function createTerminalPlatformSdkAliases(): Record<string, string> {
  if (!terminalPlatformLocalRoot) return {}

  const sdkPackage = (name: string) =>
    resolve(terminalPlatformLocalRoot, 'sdk', 'packages', name, 'dist', 'index.js')

  return {
    '@terminal-platform/design-tokens': sdkPackage('design-tokens'),
    '@terminal-platform/foundation': sdkPackage('foundation'),
    '@terminal-platform/runtime-types': sdkPackage('runtime-types'),
    '@terminal-platform/workspace-adapter-websocket': sdkPackage('workspace-adapter-websocket'),
    '@terminal-platform/workspace-contracts': sdkPackage('workspace-contracts'),
    '@terminal-platform/workspace-core': sdkPackage('workspace-core'),
    '@terminal-platform/workspace-elements': sdkPackage('workspace-elements'),
    '@terminal-platform/workspace-gateway-node': sdkPackage('workspace-gateway-node'),
    '@terminal-platform/workspace-react': sdkPackage('workspace-react'),
  }
}

export default defineConfig({
  main: {
    plugins: [
      nativeModuleStub(),
      ...createSentryPlugins('main'),
    ],
    define: {
      __APP_VERSION__: JSON.stringify(pkg.version),
      __BUILD_GIT_SHA__: JSON.stringify(buildGitSha),
      __BUILD_ID__: JSON.stringify(buildId),
      __RELEASE_CHANNEL__: JSON.stringify(releaseChannel),
      __SENTRY_ENVIRONMENT__: JSON.stringify(sentryEnvironment),
      // Inject DSN at compile time - process.env.SENTRY_DSN is NOT available
      // at runtime in packaged Electron apps (only during CI build).
      'process.env.SENTRY_DSN': JSON.stringify(process.env.SENTRY_DSN ?? ''),
    },
    resolve: {
      alias: {
        '@features': resolve(__dirname, 'src/features'),
        '@main': resolve(__dirname, 'src/main'),
        '@shared': resolve(__dirname, 'src/shared'),
        '@preload': resolve(__dirname, 'src/preload'),
        ...terminalPlatformSdkAliases
      }
    },
    build: {
      externalizeDeps: {
        exclude: bundledDeps
      },
      commonjsOptions: {
        strictRequires: [/node_modules\/.*ssh2\//],
      },
      sourcemap: sourceMapSetting,
      outDir: 'dist-electron/main',
      rollupOptions: {
        input: {
          index: resolve(__dirname, 'src/main/index.ts'),
          'team-fs-worker': resolve(__dirname, 'src/main/workers/team-fs-worker.ts'),
          'task-change-worker': resolve(__dirname, 'src/main/workers/task-change-worker.ts'),
          'team-data-worker': resolve(__dirname, 'src/main/workers/team-data-worker.ts'),
          'internal-storage-worker': resolve(
            __dirname,
            'src/features/internal-storage/main/infrastructure/worker/internalStorageWorkerEntry.ts'
          )
        },
        output: {
          // CJS format so bundled deps can use __dirname/require.
          // Use .cjs extension since package.json has "type": "module".
          format: 'cjs',
          entryFileNames: '[name].cjs',
          // Also drops the env inherited from a parent Claude Code session (see inheritedHarnessEnv.ts).
          // Set UV_THREADPOOL_SIZE before any module code runs.
          // Must be in the banner because ESM→CJS hoists imports above top-level code.
          // On Windows, fs.watch({recursive:true}) occupies a UV pool thread per watcher;
          // with 3+ watchers + concurrent fs/DNS/spawn, the default 4 threads deadlock.
          banner: `${INHERITED_HARNESS_ENV_BANNER};if(!process.env.UV_THREADPOOL_SIZE){process.env.UV_THREADPOOL_SIZE='24'}`
        }
      }
    }
  },
  preload: {
    resolve: {
      alias: {
        '@features': resolve(__dirname, 'src/features'),
        '@preload': resolve(__dirname, 'src/preload'),
        '@shared': resolve(__dirname, 'src/shared'),
        '@main': resolve(__dirname, 'src/main')
      }
    },
    build: {
      // Sandboxed preload can require Electron only; inline the portable group DTO/constants.
      externalizeDeps: {
        exclude: ['@agent-teams/legacy-agent-host']
      },
      outDir: 'dist-electron/preload',
      rollupOptions: {
        input: {
          index: resolve(__dirname, 'src/preload/index.ts')
        },
        output: {
          format: 'cjs',
          entryFileNames: '[name].js'
        }
      }
    }
  },
  renderer: {
    cacheDir: resolve(__dirname, 'node_modules/.vite/electron-renderer'),
    optimizeDeps: {
      // Electron owns the renderer runtime, so dependency prebundling can keep modern syntax.
      // This avoids esbuild trying to downlevel large ESM deps like Radix/CodeMirror/xterm.
      esbuildOptions: {
        target: rendererDependencyEsbuildTarget,
      },
      // Lazy Task dialogs use floating-ui. Discovering it after navigation would
      // force a full dev reload and discard the current in-memory tabs.
      include: ['@codemirror/language-data', '@floating-ui/dom'],
      exclude: [
        '@claude-teams/agent-graph',
        '@terminal-platform/design-tokens',
        '@terminal-platform/foundation',
        '@terminal-platform/runtime-types',
        '@terminal-platform/workspace-adapter-websocket',
        '@terminal-platform/workspace-contracts',
        '@terminal-platform/workspace-core',
        '@terminal-platform/workspace-elements',
        '@terminal-platform/workspace-gateway-node',
        '@terminal-platform/workspace-react',
      ]
    },
    define: {
      __APP_VERSION__: JSON.stringify(pkg.version),
      __BUILD_GIT_SHA__: JSON.stringify(buildGitSha),
      __BUILD_ID__: JSON.stringify(buildId),
      __RELEASE_CHANNEL__: JSON.stringify(releaseChannel),
      __SENTRY_ENVIRONMENT__: JSON.stringify(sentryEnvironment),
      __OFFICIAL_POSTHOG_BUILD__: JSON.stringify(officialPostHogBuild),
      // Pass SENTRY_DSN to renderer as VITE_SENTRY_DSN (Vite replaces at compile time)
      'import.meta.env.VITE_SENTRY_DSN': JSON.stringify(process.env.SENTRY_DSN ?? ''),
      // PostHog project API keys are public browser SDK keys. Prefer POSTHOG_* in CI.
      'import.meta.env.VITE_POSTHOG_KEY': JSON.stringify(posthogKey),
      'import.meta.env.VITE_POSTHOG_HOST': JSON.stringify(posthogHost),
    },
    resolve: {
      alias: {
        '@features': resolve(__dirname, 'src/features'),
        '@renderer': resolve(__dirname, 'src/renderer'),
        '@shared': resolve(__dirname, 'src/shared'),
        '@main': resolve(__dirname, 'src/main'),
        '@radix-ui/react-compose-refs': resolve(
          __dirname,
          'src/renderer/vendor/radixComposeRefs.ts'
        ),
        ...terminalPlatformSdkAliases,
        '@claude-teams/agent-graph': resolve(__dirname, 'packages/agent-graph/src/index.ts')
      }
    },
    plugins: [react(), fileViewerRenderers({ preset: 'office', inject: false, chunkStrategy: 'none',
      copyAssets: { baseDir: 'file-viewer', publicDir: resolve(__dirname, 'node_modules/.cache/document-preview-public') } }),
      ...createSentryPlugins('renderer')],
    publicDir: resolve(__dirname, 'src/renderer/public'),
    build: {
      sourcemap: sourceMapSetting,
      rollupOptions: {
        input: {
          index: resolve(__dirname, 'src/renderer/index.html'),
          'document-preview': resolve(__dirname, 'src/renderer/document-preview.html')
        },
        output: {
          // OpenUI's catalog imports Lucide's lazy icon map. Keep it in one
          // chunk instead of emitting a separate file for every unused icon.
          manualChunks(id, { getModuleInfo }) {
            if (
              id.includes('/lucide-react/dist/esm/icons/') &&
              getModuleInfo(id)?.dynamicImporters.some((importer) =>
                importer.endsWith('/lucide-react/dist/esm/dynamicIconImports.js')
              )
            ) return 'openui-icons'
          }
        }
      }
    }
  }
})

interface McpManifestSource {
  name: string;
  version: string;
  engines: Record<string, string>;
}

/** The distributed server bundles its dependencies into index.js. */
export function createMcpDeploymentManifest(source: McpManifestSource) {
  return {
    name: source.name,
    version: source.version,
    private: true,
    type: 'module',
    main: 'index.js',
    engines: source.engines,
  };
}

#!/usr/bin/env node
import { realpathSync } from 'fs';
import type { IncomingMessage, ServerResponse } from 'node:http';
import { fileURLToPath } from 'url';

import { FastMCP } from 'fastmcp';

import { registerTools, type McpToolProfile } from './tools';

const HTTP_TRANSPORT = 'httpStream';
const STDIO_TRANSPORT = 'stdio';
const DEFAULT_HTTP_HOST = '127.0.0.1';
const DEFAULT_HTTP_ENDPOINT = '/mcp';
const MCP_HTTP_IDENTITY_SERVICE = 'agent-teams-mcp-http';
const MCP_HTTP_IDENTITY_SERVICE_ENV = 'AGENT_TEAMS_MCP_HTTP_IDENTITY_SERVICE';
const MCP_HTTP_CLAUDE_DIR_HASH_ENV = 'AGENT_TEAMS_MCP_HTTP_CLAUDE_DIR_HASH';
const MCP_HTTP_LAUNCH_SPEC_HASH_ENV = 'AGENT_TEAMS_MCP_HTTP_LAUNCH_SPEC_HASH';
const MCP_HTTP_OWNER_INSTANCE_ID_ENV = 'AGENT_TEAMS_MCP_HTTP_OWNER_INSTANCE_ID';

export type AgentTeamsMcpStartOptions =
  | {
      transportType: typeof STDIO_TRANSPORT;
    }
  | {
      transportType: typeof HTTP_TRANSPORT;
      httpStream: {
        host: string;
        port: number;
        endpoint: `/${string}`;
      };
    };

export interface AgentTeamsMcpHttpHealthIdentity {
  schemaVersion: 1;
  service: typeof MCP_HTTP_IDENTITY_SERVICE;
  transport: typeof HTTP_TRANSPORT;
  host: string;
  port: number;
  endpoint: `/${string}`;
  claudeDirHash: string;
  launchSpecHash: string;
  ownerInstanceId: string;
}

export function createServer(
  input: {
    healthIdentity?: AgentTeamsMcpHttpHealthIdentity | null;
    startOptions?: AgentTeamsMcpStartOptions;
    toolProfile?: McpToolProfile;
  } = {}
) {
  const httpOptions =
    input.startOptions?.transportType === HTTP_TRANSPORT ? input.startOptions.httpStream : null;
  const bound =
    process.env.AGENT_TEAMS_BOUND_CONTROL_URL !== undefined ||
    process.env.AGENT_TEAMS_BOUND_CONTEXT_JSON !== undefined;
  if (
    input.toolProfile === 'management' &&
    (!process.env.AGENT_TEAMS_BOUND_CONTROL_URL || !process.env.AGENT_TEAMS_BOUND_CONTEXT_JSON)
  ) {
    throw new Error('Management MCP requires a bound desktop context');
  }
  if (bound && httpOptions && !['127.0.0.1', '::1', 'localhost'].includes(httpOptions.host)) {
    throw new Error('Desktop-bound MCP must listen on loopback');
  }
  const authorityHost = httpOptions?.host === '::1' ? '[::1]' : httpOptions?.host;
  const authority = httpOptions ? `${authorityHost}:${httpOptions.port}` : null;
  const server = new FastMCP({
    name: 'agent-teams-mcp',
    version: '1.0.0',
    ...(bound && authority
      ? {
          // Patched transport admission covers every method, before CORS and session lookup.
          httpRequestGate: (request: IncomingMessage, response: ServerResponse) => {
            if (
              request.headers.host !== authority ||
              (request.headers.origin !== undefined &&
                request.headers.origin !== `http://${authority}`)
            ) {
              response.writeHead(403, { 'content-type': 'application/json' });
              response.end(JSON.stringify({ error: 'Forbidden Host or Origin' }));
              return false;
            }
            return true;
          },
        }
      : {}),
    ...(input.healthIdentity
      ? {
          health: {
            enabled: true,
            path: '/health',
            status: 200,
            message: JSON.stringify(input.healthIdentity),
          },
        }
      : {}),
  });

  registerTools(server, input.toolProfile);

  return server;
}

function getArgValue(argv: string[], name: string): string | null {
  const directPrefix = `${name}=`;
  for (let index = 2; index < argv.length; index += 1) {
    const value = argv[index];
    if (value === name) {
      return argv[index + 1] ?? null;
    }
    if (value.startsWith(directPrefix)) {
      return value.slice(directPrefix.length);
    }
  }
  return null;
}

export function resolveToolProfile(argv: string[] = process.argv): McpToolProfile {
  const profile = getArgValue(argv, '--tool-profile') ?? 'full';
  if (profile !== 'full' && profile !== 'management') {
    throw new Error(`Unknown MCP tool profile: ${profile}`);
  }
  return profile;
}

function normalizeEndpoint(value: string | null | undefined): `/${string}` {
  const trimmed = value?.trim();
  if (!trimmed) {
    return DEFAULT_HTTP_ENDPOINT;
  }
  return (trimmed.startsWith('/') ? trimmed : `/${trimmed}`) as `/${string}`;
}

function parsePort(value: string | null | undefined): number {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed <= 0 || parsed > 65535) {
    throw new Error(`Invalid agent-teams MCP HTTP port: ${value ?? '<empty>'}`);
  }
  return parsed;
}

function readIdentityValue(env: NodeJS.ProcessEnv, name: string): string | null {
  const value = env[name]?.trim();
  return value && value.length > 0 ? value : null;
}

export function buildHttpHealthIdentity(
  options: AgentTeamsMcpStartOptions,
  env: NodeJS.ProcessEnv = process.env
): AgentTeamsMcpHttpHealthIdentity | null {
  if (options.transportType !== HTTP_TRANSPORT) {
    return null;
  }

  const service = readIdentityValue(env, MCP_HTTP_IDENTITY_SERVICE_ENV);
  const claudeDirHash = readIdentityValue(env, MCP_HTTP_CLAUDE_DIR_HASH_ENV);
  const launchSpecHash = readIdentityValue(env, MCP_HTTP_LAUNCH_SPEC_HASH_ENV);
  const ownerInstanceId = readIdentityValue(env, MCP_HTTP_OWNER_INSTANCE_ID_ENV);
  if (
    service !== MCP_HTTP_IDENTITY_SERVICE ||
    !claudeDirHash ||
    !launchSpecHash ||
    !ownerInstanceId
  ) {
    return null;
  }

  return {
    schemaVersion: 1,
    service: MCP_HTTP_IDENTITY_SERVICE,
    transport: HTTP_TRANSPORT,
    host: options.httpStream.host,
    port: options.httpStream.port,
    endpoint: options.httpStream.endpoint,
    claudeDirHash,
    launchSpecHash,
    ownerInstanceId,
  };
}

export function resolveStartOptions(
  argv: string[] = process.argv,
  env: NodeJS.ProcessEnv = process.env
): AgentTeamsMcpStartOptions {
  const transport =
    getArgValue(argv, '--transport') ??
    getArgValue(argv, '--transportType') ??
    env.AGENT_TEAMS_MCP_TRANSPORT ??
    STDIO_TRANSPORT;

  if (transport !== HTTP_TRANSPORT) {
    return { transportType: STDIO_TRANSPORT };
  }

  return {
    transportType: HTTP_TRANSPORT,
    httpStream: {
      host:
        getArgValue(argv, '--host')?.trim() ??
        env.AGENT_TEAMS_MCP_HTTP_HOST?.trim() ??
        DEFAULT_HTTP_HOST,
      port: parsePort(getArgValue(argv, '--port') ?? env.AGENT_TEAMS_MCP_HTTP_PORT),
      endpoint: normalizeEndpoint(
        getArgValue(argv, '--endpoint') ?? env.AGENT_TEAMS_MCP_HTTP_ENDPOINT
      ),
    },
  };
}

async function main(): Promise<void> {
  const startOptions = resolveStartOptions();
  const server = createServer({
    startOptions,
    toolProfile: resolveToolProfile(),
    healthIdentity: buildHttpHealthIdentity(startOptions),
  });
  await server.start(startOptions);
}

function isEntrypoint(argv: string[] = process.argv): boolean {
  const entryPath = argv[1];
  if (!entryPath) {
    return false;
  }
  try {
    return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(entryPath);
  } catch {
    return fileURLToPath(import.meta.url) === entryPath;
  }
}

if (isEntrypoint()) {
  main().catch((error) => {
    console.error(error instanceof Error ? (error.stack ?? error.message) : String(error));
    process.exitCode = 1;
  });
}

{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "rootDir": ".",
    "noEmit": true,
    "types": ["node", "vitest/globals"]
  },
  "include": ["src/**/*.ts", "test/**/*.ts"],
  "exclude": ["node_modules", "dist"]
}

import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

import { defineConfig } from 'tsup';

import { createMcpDeploymentManifest } from './deploymentManifest';

export default defineConfig((overrideOptions) => ({
  entry: ['src/index.ts'],
  format: ['esm'],
  target: 'node24',
  platform: 'node',
  outDir: 'dist',
  clean: true,
  sourcemap: true,
  dts: false,
  // Bundle all dependencies into a single self-contained file so the packaged
  // Electron app can run the MCP server without a node_modules tree.
  noExternal: [/.*/],
  splitting: false,
  async onSuccess() {
    const source = JSON.parse(await readFile(new URL('./package.json', import.meta.url), 'utf8'));
    await writeFile(
      resolve(overrideOptions.outDir ?? 'dist', 'package.json'),
      `${JSON.stringify(createMcpDeploymentManifest(source), null, 2)}\n`
    );
  },
  // Provide a real `require` function for CJS dependencies (e.g. undici)
  // that use require() for Node built-in modules.
  banner: {
    js: `import { createRequire as __bundled_createRequire } from 'module';\nconst require = __bundled_createRequire(import.meta.url);`,
  },
  esbuildOptions(options) {
    // Optional peer deps of xsschema (pulled in by fastmcp) — we only use zod.
    // Mark as external at the esbuild level to avoid resolution errors.
    options.external = [
      ...(options.external ?? []),
      'sury',
      '@valibot/to-json-schema',
