import { createHash, randomUUID } from 'node:crypto';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';

import { execCli } from '@main/utils/childProcess';
import { resolveElectronNodeLaunch } from '@main/utils/electronNodeLaunch';

interface BundleReceipt {
  inputs: string;
  entry: string;
  output: string;
}

interface WorkspaceBuild {
  receipt?: BundleReceipt;
  pending?: Promise<string>;
}

const workspaces = new Map<string, WorkspaceBuild>();
const BUILD_TIMEOUT_MS = 120_000;
const INPUT_FILES = [
  'package.json',
  'pnpm-lock.yaml',
  'pnpm-workspace.yaml',
  'mcp-server/package.json',
  'mcp-server/tsconfig.json',
  'mcp-server/tsup.config.ts',
  'mcp-server/deploymentManifest.ts',
  'agent-teams-controller/package.json',
];

async function fingerprintInputs(root: string): Promise<string> {
  const files = [...INPUT_FILES];
  const directories = new Set<string>();
  async function collect(directory: string): Promise<void> {
    const physical = await fs.realpath(path.join(root, directory));
    const relativePhysical = path.relative(root, physical);
    if (
      relativePhysical === '..' ||
      relativePhysical.startsWith(`..${path.sep}`) ||
      path.isAbsolute(relativePhysical)
    ) {
      throw new Error('MCP_BUNDLE_SOURCE_LINK: MCP source directories must stay in the workspace.');
    }
    if (directories.has(physical)) {
      throw new Error('MCP_BUNDLE_SOURCE_LINK: MCP source directory cycle or alias.');
    }
    directories.add(physical);
    for (const item of await fs.readdir(path.join(root, directory), { withFileTypes: true })) {
      const relative = path.join(directory, item.name);
      if (item.isDirectory()) await collect(relative);
      else if (item.isFile()) files.push(relative);
      else if (item.isSymbolicLink()) {
        throw new Error('MCP_BUNDLE_SOURCE_LINK: Linked MCP source entries are unsupported.');
      }
    }
  }
  await collect('mcp-server/src');
  await collect('agent-teams-controller/src');
  const hash = createHash('sha256');
  for (const relative of files.toSorted((left, right) => left.localeCompare(right))) {
    const bytes = await fs.readFile(path.join(root, relative));
    hash.update(JSON.stringify([relative, bytes.length]));
    hash.update(bytes);
  }
  return hash.digest('hex');
}

async function outputHash(entry: string): Promise<string | null> {
  try {
    return createHash('sha256')
      .update(await fs.readFile(entry))
      .update('\0')
      .update(await fs.readFile(path.join(path.dirname(entry), 'package.json')))
      .digest('hex');
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
    throw error;
  }
}

async function buildCurrentBundle(
  root: string,
  node: string,
  outputRoot: string,
  state: WorkspaceBuild
): Promise<string> {
  const inputs = await fingerprintInputs(root);
  if (state.receipt?.inputs === inputs) {
    if ((await outputHash(state.receipt.entry)) === state.receipt.output)
      return state.receipt.entry;
  }
  // Every app process builds once before trusting dist. Each generation has its
  // own directory, so rebuilding cannot remove a bundle another child is loading.
  // Retain app-owned generations across builds and app exit: saved launch
  // configs and native clients can outlive the development app process.
  state.receipt = undefined;
  const server = path.join(root, 'mcp-server');
  const outputDirectory = path.join(outputRoot, 'dev', `${process.pid}-${randomUUID()}`);
  const entry = path.join(outputDirectory, 'index.js');
  try {
    const launch = await resolveElectronNodeLaunch(node, [
      await fs.realpath(path.join(server, 'node_modules', 'tsup', 'dist', 'cli-default.js')),
      '--out-dir',
      outputDirectory,
    ], 'generic');
    await execCli(launch.command, launch.args, {
      cwd: server,
      timeout: BUILD_TIMEOUT_MS,
      stdoutMaxBuffer: 128 * 1024,
      stderrMaxBuffer: 128 * 1024,
    });
    if ((await fingerprintInputs(root)) !== inputs) {
      throw new Error(
        'MCP_BUNDLE_INPUTS_CHANGED: MCP sources changed during the build; retry launch.'
      );
    }
    // Keep the builder's genuine deployment identity. OpenCode V2 qualifies the
    // selected MCP entry by its named/versioned package, even for dev bundles.
    const output = await outputHash(entry);
    if (!output) throw new Error('MCP_BUNDLE_MISSING: MCP build did not produce its entrypoint.');
    state.receipt = { inputs, entry, output };
    return entry;
  } catch (error) {
    await fs.rm(outputDirectory, { recursive: true, force: true });
    throw error;
  }
}

/** Compile before the client's handshake clock starts; never fall back to stale JS. */
export async function resolveWorkspaceMcpBundle(
  root: string,
  node: string,
  outputRoot: string
): Promise<string> {
  const workspace = await fs.realpath(root);
  const destination = path.resolve(outputRoot);
  const key = `${workspace}\0${destination}`;
  let state = workspaces.get(key);
  if (!state) {
    state = {};
    workspaces.set(key, state);
  }
  if (state.pending) return state.pending;
  const pending = buildCurrentBundle(workspace, node, destination, state);
  state.pending = pending;
  try {
    return await pending;
  } finally {
    state.pending = undefined;
  }
}

import { createHash } from 'node:crypto';
import {
  accessSync,
  closeSync,
  constants,
  fstatSync,
  lstatSync,
  openSync,
  readdirSync,
  readSync,
  realpathSync,
} from 'node:fs';
import { isAbsolute, join, resolve } from 'node:path';

import type { BigIntStats } from 'node:fs';

// This association is updated only with the reviewed native source and its qualification.
export const LINUX_NODE_EXEC_SOURCE_SHA256 = '4a6e27406a7c1125cadcef66fc54cf10160b82d920a9b7d516f01ca467426dd3';
const FILE_NAME = 'node-exec';
const MANIFEST_NAME = 'manifest.json';
const DIGEST = /^[a-f0-9]{64}$/;
type Identity = Pick<BigIntStats, 'dev' | 'ino' | 'size' | 'mtimeNs' | 'ctimeNs'>;

export interface LinuxNodeExecArtifact {
  readonly directory: string;
  readonly path: string;
  readonly manifestSha256: string;
  readonly binarySha256: string;
  readonly directoryIdentity: Readonly<Identity>;
  readonly manifestIdentity: Readonly<Identity>;
  readonly binaryIdentity: Readonly<Identity>;
}

const invalid = (): Error => new Error('Linux Node process launcher is unavailable or changed');
const identity = (stat: BigIntStats): Readonly<Identity> => Object.freeze({
  dev: stat.dev, ino: stat.ino, size: stat.size, mtimeNs: stat.mtimeNs, ctimeNs: stat.ctimeNs,
});
const same = (left: Readonly<Identity>, right: Readonly<Identity>): boolean =>
  left.dev === right.dev && left.ino === right.ino && left.size === right.size &&
  left.mtimeNs === right.mtimeNs && left.ctimeNs === right.ctimeNs;

function readOriginalFile(path: string, maximum: number, executable = false) {
  const fd = openSync(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const before = fstatSync(fd, { bigint: true });
    if (!before.isFile() || before.size <= 0n || before.size > BigInt(maximum) ||
        (before.mode & 0o022n) !== 0n || (executable && (before.mode & 0o111n) === 0n))
      throw invalid();
    const bytes = Buffer.alloc(Number(before.size) + 1);
    let length = 0;
    while (length < bytes.length) {
      const count = readSync(fd, bytes, length, bytes.length - length, null);
      if (!count) break;
      length += count;
    }
    const after = fstatSync(fd, { bigint: true }), named = lstatSync(path, { bigint: true });
    if (length !== Number(before.size) || !same(before, after) || !same(before, named) ||
        named.isSymbolicLink() || realpathSync(path) !== path)
      throw invalid();
    const content = bytes.subarray(0, length);
    return { bytes: content, sha256: createHash('sha256').update(content).digest('hex'),
      identity: identity(before) };
  } finally {
    closeSync(fd);
  }
}

/** Reject a dynamic loader dependency: this small Linux stage must not raise the app's libc floor. */
export function assertStaticLinuxNodeExec(bytes: Buffer): void {
  if (bytes.length < 64 || bytes.subarray(0, 7).toString('hex') !== '7f454c46020101' ||
      bytes.readUInt16LE(18) !== 62 || ![2, 3].includes(bytes.readUInt16LE(16)))
    throw invalid();
  const offset = bytes.readBigUInt64LE(32), entrySize = bytes.readUInt16LE(54),
    count = bytes.readUInt16LE(56);
  if (offset > BigInt(bytes.length) || entrySize < 56 || !count || count > 128 ||
      offset + BigInt(entrySize * count) > BigInt(bytes.length))
    throw invalid();
  for (let index = 0; index < count; index++) {
    const type = bytes.readUInt32LE(Number(offset) + index * entrySize);
    // The qualified static executable has neither PT_INTERP nor PT_DYNAMIC.
    if (type === 3 || type === 2) throw invalid();
  }
}

/** Trusted app resource directory only. No renderer/tool argument selects this artifact. */
export function captureLinuxNodeExecArtifact(directory: string): LinuxNodeExecArtifact {
  if (process.platform !== 'linux' || process.arch !== 'x64' ||
      !isAbsolute(directory) || resolve(directory) !== directory || realpathSync(directory) !== directory)
    throw invalid();
  const before = lstatSync(directory, { bigint: true });
  if (!before.isDirectory() || before.isSymbolicLink() || (before.mode & 0o022n) !== 0n ||
      readdirSync(directory).sort().join(',') !== 'manifest.json,node-exec')
    throw invalid();
  const manifest = readOriginalFile(join(directory, MANIFEST_NAME), 16 * 1024);
  const record: unknown = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(manifest.bytes));
  if (!record || typeof record !== 'object' || Array.isArray(record)) throw invalid();
  const row = record as Record<string, unknown>;
  if (Object.keys(row).sort().join(',') !==
      'architecture,binarySha256,compilerSha256,file,platform,schemaVersion,sourceSha256,static' ||
      row.schemaVersion !== 1 || row.platform !== 'linux' || row.architecture !== 'x64' ||
      row.file !== FILE_NAME || row.static !== true ||
      row.sourceSha256 !== LINUX_NODE_EXEC_SOURCE_SHA256 ||
      typeof row.binarySha256 !== 'string' || !DIGEST.test(row.binarySha256) ||
      typeof row.compilerSha256 !== 'string' || !DIGEST.test(row.compilerSha256))
    throw invalid();
  const path = join(directory, FILE_NAME), binary = readOriginalFile(path, 4 * 1024 * 1024, true);
  if (binary.sha256 !== row.binarySha256) throw invalid();
  assertStaticLinuxNodeExec(binary.bytes);
  accessSync(path, constants.X_OK);
  const after = lstatSync(directory, { bigint: true });
  if (!same(before, after)) throw invalid();
  return Object.freeze({
    directory, path, manifestSha256: manifest.sha256, binarySha256: binary.sha256,
    directoryIdentity: identity(before), manifestIdentity: manifest.identity, binaryIdentity: binary.identity,
  });
}

/** Recheck the captured artifact without adopting a replacement directory or image. */
export function validateLinuxNodeExecArtifact(selected: LinuxNodeExecArtifact): void {
  const current = captureLinuxNodeExecArtifact(selected.directory);
  if (current.path !== selected.path || current.manifestSha256 !== selected.manifestSha256 ||
      current.binarySha256 !== selected.binarySha256 ||
      !same(current.directoryIdentity, selected.directoryIdentity) ||
      !same(current.manifestIdentity, selected.manifestIdentity) ||
      !same(current.binaryIdentity, selected.binaryIdentity))
    throw invalid();
}

type BuildEnvironment = Readonly<Record<string, string | undefined>>;

function firstNonEmptyEnv(...values: Array<string | undefined>): string {
  return values.map((value) => value?.trim() ?? '').find(Boolean) ?? '';
}

export function isOfficialPostHogReleaseBuild(env: BuildEnvironment): boolean {
  return (
    String(env.IS_RELEASE_BUILD ?? '').toLowerCase() === 'true' ||
    Boolean(firstNonEmptyEnv(env.RELEASE_TAG)) ||
    env.GITHUB_EVENT_NAME === 'workflow_dispatch'
  );
}

export function resolvePostHogBuildKey(env: BuildEnvironment, localEnv: BuildEnvironment): string {
  if (!isOfficialPostHogReleaseBuild(env)) {
    return '';
  }

  return firstNonEmptyEnv(
    env.POSTHOG_KEY,
    localEnv.POSTHOG_KEY,
    env.VITE_POSTHOG_KEY,
    localEnv.VITE_POSTHOG_KEY
  );
}

/** Application-owned build contract. These records never contain filesystem roots or map content. */
export const SENTRY_INVENTORY_FILE = 'sentry-artifact-inventory.json';
export const SENTRY_INVENTORY_PAYLOAD_ID = 'sentry-artifact-inventory';
export const SENTRY_INVENTORY_MAX_BYTES = 256 * 1024;
export const SENTRY_INVENTORY_MAX_ARTIFACTS = 1024;
export const SENTRY_DEBUG_ID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
export const SENTRY_TARGET_PREFIXES = {
  main: 'dist-electron/main/',
  renderer: 'out/renderer/',
  preload: 'dist-electron/preload/',
} as const;

export type SentryArtifactTarget = keyof typeof SENTRY_TARGET_PREFIXES;
export type SentryBuildIdentity = Readonly<{ release: string; buildId: string; gitSha: string }>;
export type SentryRuntimeArtifact = Readonly<{
  target: SentryArtifactTarget;
  relativeFile: string;
  locator: string;
  debugId: string;
}>;
export type SentryRuntimeInventory = SentryBuildIdentity &
  Readonly<{
    schemaVersion: 1;
    artifacts: readonly SentryRuntimeArtifact[];
    coverage: Readonly<Record<SentryArtifactTarget, 'covered' | 'uncovered'>>;
  }>;

export function isSentryArtifactFile(value: string): boolean {
  return (
    value.length <= 512 &&
    /^[A-Za-z0-9_./-]+\.(?:js|cjs|mjs)$/.test(value) &&
    value.split('/').every((segment) => segment !== '' && segment !== '.' && segment !== '..')
  );
}

function object(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function exactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}
function identityToken(value: unknown, allowEmpty: boolean): value is string {
  return (
    typeof value === 'string' &&
    ((allowEmpty && value === '') || /^[A-Za-z0-9][A-Za-z0-9._@+-]{0,159}$/.test(value))
  );
}

/** Bounded, strict and fail-closed. Copy/freeze admitted data rather than retaining untrusted objects. */
export function parseSentryArtifactInventory(
  json: string,
  expected: SentryBuildIdentity
): SentryRuntimeInventory | null {
  if (
    json.length > SENTRY_INVENTORY_MAX_BYTES ||
    new TextEncoder().encode(json).length > SENTRY_INVENTORY_MAX_BYTES
  )
    return null;
  try {
    const value: unknown = JSON.parse(json);
    if (
      !object(value) ||
      !exactKeys(value, [
        'schemaVersion',
        'release',
        'buildId',
        'gitSha',
        'artifacts',
        'coverage',
      ]) ||
      value.schemaVersion !== 1 ||
      !identityToken(value.release, false) ||
      !identityToken(value.buildId, true) ||
      typeof value.gitSha !== 'string' ||
      (value.gitSha !== '' && !/^[0-9a-f]{40}$/.test(value.gitSha)) ||
      value.release !== expected.release ||
      value.buildId !== expected.buildId ||
      value.gitSha !== expected.gitSha ||
      !object(value.coverage) ||
      !exactKeys(value.coverage, ['main', 'renderer', 'preload']) ||
      !Array.isArray(value.artifacts) ||
      value.artifacts.length > SENTRY_INVENTORY_MAX_ARTIFACTS
    )
      return null;
    const coverage = value.coverage;
    if (Object.values(coverage).some((status) => status !== 'covered' && status !== 'uncovered'))
      return null;
    if (Object.values(coverage).includes('covered') && (!value.buildId || !value.gitSha))
      return null;
    const artifacts: SentryRuntimeArtifact[] = [];
    let previous = '';
    for (const row of value.artifacts) {
      if (
        !object(row) ||
        !exactKeys(row, ['target', 'relativeFile', 'locator', 'debugId']) ||
        typeof row.target !== 'string' ||
        !Object.hasOwn(SENTRY_TARGET_PREFIXES, row.target) ||
        typeof row.relativeFile !== 'string' ||
        !isSentryArtifactFile(row.relativeFile) ||
        typeof row.locator !== 'string' ||
        row.locator !== `app:///${row.relativeFile}` ||
        typeof row.debugId !== 'string' ||
        !SENTRY_DEBUG_ID_PATTERN.test(row.debugId)
      )
        return null;
      const target = row.target as SentryArtifactTarget;
      if (
        coverage[target] !== 'covered' ||
        !row.relativeFile.startsWith(SENTRY_TARGET_PREFIXES[target]) ||
        row.locator <= previous
      )
        return null;
      previous = row.locator;
      artifacts.push(
        Object.freeze({
          target,
          relativeFile: row.relativeFile,
          locator: row.locator,
          debugId: row.debugId,
        })
      );
    }
    if (
      Object.keys(SENTRY_TARGET_PREFIXES).some(
        (target) =>
          coverage[target] === 'covered' && !artifacts.some((row) => row.target === target)
      )
    )
      return null;
    return Object.freeze({
      schemaVersion: 1,
      release: value.release,
      buildId: value.buildId,
      gitSha: value.gitSha,
      artifacts: Object.freeze(artifacts),
      coverage: Object.freeze({
        main: coverage.main,
        renderer: coverage.renderer,
        preload: coverage.preload,
      }),
    }) as SentryRuntimeInventory;
  } catch {
    return null;
  }
}

export type SentryBuildEnvironment = 'production' | 'development';

function firstNonEmptyEnv(
  env: Readonly<Record<string, string | undefined>>,
  ...names: string[]
): string {
  return names.map((name) => env[name]?.trim() ?? '').find(Boolean) ?? '';
}

/**
 * Resolve the Sentry environment at build time.
 *
 * Packaged Electron apps do not reliably preserve NODE_ENV at runtime, so
 * official release metadata is the canonical production signal.
 */
export function resolveSentryBuildEnvironment(
  env: Readonly<Record<string, string | undefined>>
): SentryBuildEnvironment {
  const releaseTag = firstNonEmptyEnv(env, 'RELEASE_TAG');
  const githubRef = firstNonEmptyEnv(env, 'GITHUB_REF');
  const isOfficialRelease =
    env.IS_RELEASE_BUILD?.trim().toLowerCase() === 'true' ||
    /^v[0-9]/.test(releaseTag) ||
    /^refs\/tags\/v[0-9]/.test(githubRef);

  return isOfficialRelease || env.NODE_ENV === 'production' ? 'production' : 'development';
}

/** @type {import('tailwindcss').Config} */
const defaultFontSizes = require('tailwindcss/defaultTheme').fontSize;

// Scale glyphs and line boxes, not rem-based layout spacing or Electron/browser zoom.
const scaledFontSizes = Object.fromEntries(
  Object.entries(defaultFontSizes).map(([name, [size, options]]) => [
    name,
    [
      `calc(${size} * var(--appearance-text-scale, 1))`,
      {
        ...options,
        lineHeight: Number.isFinite(Number(options.lineHeight))
          ? options.lineHeight
          : `calc(${options.lineHeight} * var(--appearance-text-scale, 1))`,
      },
    ],
  ])
);

module.exports = {
  darkMode: ['class'],
  content: [
    './src/renderer/index.html',
    './src/renderer/**/*.{js,ts,jsx,tsx}',
    './src/features/**/*.{js,ts,jsx,tsx}',
